// ref shader from https://openprocessing.org/sketch/1625592 

var p = [];
var mySize, margin;
var seed = Math.random() * 5292;
let colors1 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
let colorset = [];
let colorbg;
let filter1;
let theShader;
let webGLCanvas;
let originalGraphics;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	randomSeed(seed);
	margin = 0;
	createCanvas(1112, 834);
	mySize = height;
	webGLCanvas = createGraphics(width, height, WEBGL);
	originalGraphics = createGraphics(width, height);
	for (let i = 0; i < int(random(500, 100)); i++) {
		p[i] = createVector(random(-width * 0.5, width * 1.5), random(-height * 0.5, height * 1.5));
	}
	// pixelDensity(5);
	colorbg = random(colors1);
	colorset[0] = random(colors2);
	colorset[1] = random(colors2);
	colorset[2] = random(colors1);
	colorset[3] = random(colors2);
	colorset[4] = random(colors2);
	background("#202020");
	filter1 = new makeFilter();
}

function draw() {
	background("#202020");
	randomSeed(seed);
	webGLCanvas.shader(theShader);
	theShader.setUniform('u_resolution', [width / width, height / height]);
	theShader.setUniform('u_time', millis() / 1);
	theShader.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height]);
	theShader.setUniform('u_tex', originalGraphics);
	webGLCanvas.clear()

	webGLCanvas.rect(-width / 2, -height / 2, width, height);

	noiseSeed(seed);
	// blendMode(DIFFERENCE);

	//shape
	for (let newp of p) {
		let version = random([200, 150, 77, 50, 140]) * 100;

		// parameter01
		let b1 = noise(newp.x / version, newp.y / version) * TWO_PI;

		// parameter02
		let c = random(1000, 2000);

		// *** main point *** //
		// build new b based on b and c
		b2 = (TWO_PI / c) * int((b1 / TWO_PI) * c);

		newp.add(sin(b2), cos(b2));

		originalGraphics.push();
		originalGraphics.translate(newp.x, newp.y);
		let gard_w = random(mySize / 10);
		let gard_h = random(mySize / 2);

		if (b1 < 1.75) {
			originalGraphics.noStroke();
			originalGraphics.fill(0);
			let grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, colorset[0]);
			grad.addColorStop(1, str(random(colors1)) + "00");
			originalGraphics.drawingContext.fillStyle = grad;
		} else if (b1 > 1.75 && b1 < 2.25) {
			originalGraphics.noStroke();
			originalGraphics.fill(random(colors1));
			var grad = drawingContext.createRadialGradient(0, 0, 0, 0, 0, gard_h);
			grad.addColorStop(0, colorset[1]);
			grad.addColorStop(1, str(random(colors1)) + "00");
			originalGraphics.drawingContext.fillStyle = grad;
		} else if (b1 > 2.25 && b1 < 2.75) {
			originalGraphics.noStroke();
			originalGraphics.fill(0);
			var grad = drawingContext.createRadialGradient(0, 0, 0, 0, 0, gard_w);
			grad.addColorStop(0, colorset[2]);
			grad.addColorStop(1, str(random(colors2)) + "00");
			originalGraphics.drawingContext.fillStyle = grad;
		} else if (b1 > 3 && b1 < 3.75) {
			originalGraphics.noStroke();
			originalGraphics.fill(0);
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, colorset[3]);
			grad.addColorStop(1, str(random(colors2)) + "00");
			originalGraphics.drawingContext.fillStyle = grad;
		} else {
			originalGraphics.noStroke();
			originalGraphics.fill(0);
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, colorset[4]);
			grad.addColorStop(1, str(random(colors1)) + "00");
			originalGraphics.drawingContext.fillStyle = grad;
		}

		originalGraphics.push();
		originalGraphics.translate(random(gard_h), random(gard_h));
		originalGraphics.circle(0, 0, random(gard_h));
		originalGraphics.pop();

		originalGraphics.push();
		originalGraphics.translate(random(gard_w), random(gard_w));
		originalGraphics.circle(0, 0, random(gard_w));
		originalGraphics.pop();
		originalGraphics.pop();
	}

	image(webGLCanvas, 0, 0)

	image(overAllTexture, 0, 0);
	noFill();
	stroke("#202020");
	strokeWeight(margin);
	blendMode(BLEND);
	rectMode(CORNER);
	rect(0, 0, width, height);
	// noLoop();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("0831_Several blobs_shaders_2022", "png");
	}
}

//filter
function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 21, 10, 10, 10);
	drawingContext.shadowColor = color(110, 10, 51, 5);
	overAllTexture = createGraphics(width, height);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) { // noprotect
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					99,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: frag_functions_default ===
const frag_functions_default = `
  #define PI 3.141592653589793
  #define TAU 6.283185307179586

	float rand(vec2 c){
		return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
	}

	mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
	}

	mat2 scale2d(vec2 _scale){
			return mat2(_scale.x,0.0,
									0.0,_scale.y);
	}

	vec2 tile (vec2 _st, float _zoom) {
			_st *= _zoom;
			return fract(_st);
	}

	//	Classic Perlin 3D Noise 
	//	by Stefan Gustavson

	vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
	vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
	vec3 fade(vec3 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}

	float cnoise(vec3 P){
		vec3 Pi0 = floor(P); // Integer part for indexing
		vec3 Pi1 = Pi0 + vec3(1.0); // Integer part + 1
		Pi0 = mod(Pi0, 289.0);
		Pi1 = mod(Pi1, 289.0);
		vec3 Pf0 = fract(P); // Fractional part for interpolation
		vec3 Pf1 = Pf0 - vec3(1.0); // Fractional part - 1.0
		vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
		vec4 iy = vec4(Pi0.yy, Pi1.yy);
		vec4 iz0 = Pi0.zzzz;
		vec4 iz1 = Pi1.zzzz;

		vec4 ixy = permute(permute(ix) + iy);
		vec4 ixy0 = permute(ixy + iz0);
		vec4 ixy1 = permute(ixy + iz1);

		vec4 gx0 = ixy0 / 7.0;
		vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
		gx0 = fract(gx0);
		vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
		vec4 sz0 = step(gz0, vec4(0.0));
		gx0 -= sz0 * (step(0.0, gx0) - 0.5);
		gy0 -= sz0 * (step(0.0, gy0) - 0.5);

		vec4 gx1 = ixy1 / 7.0;
		vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
		gx1 = fract(gx1);
		vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
		vec4 sz1 = step(gz1, vec4(0.0));
		gx1 -= sz1 * (step(0.0, gx1) - 0.5);
		gy1 -= sz1 * (step(0.0, gy1) - 0.5);

		vec3 g000 = vec3(gx0.x,gy0.x,gz0.x);
		vec3 g100 = vec3(gx0.y,gy0.y,gz0.y);
		vec3 g010 = vec3(gx0.z,gy0.z,gz0.z);
		vec3 g110 = vec3(gx0.w,gy0.w,gz0.w);
		vec3 g001 = vec3(gx1.x,gy1.x,gz1.x);
		vec3 g101 = vec3(gx1.y,gy1.y,gz1.y);
		vec3 g011 = vec3(gx1.z,gy1.z,gz1.z);
		vec3 g111 = vec3(gx1.w,gy1.w,gz1.w);

		vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
		g000 *= norm0.x;
		g010 *= norm0.y;
		g100 *= norm0.z;
		g110 *= norm0.w;
		vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
		g001 *= norm1.x;
		g011 *= norm1.y;
		g101 *= norm1.z;
		g111 *= norm1.w;

		float n000 = dot(g000, Pf0);
		float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
		float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
		float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
		float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
		float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
		float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
		float n111 = dot(g111, Pf1);

		vec3 fade_xyz = fade(Pf0);
		vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
		vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
		float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x); 
		return 2.2 * n_xyz;
	}


float noise(vec2 p, float freq ){
	float unit = 1./freq;
	vec2 ij = floor(p/unit);
	vec2 xy = mod(p,unit)/unit;
	//xy = 3.*xy*xy-2.*xy*xy*xy;
	xy = .5*(1.-cos(PI*xy));
	float a = rand((ij+vec2(0.,0.)));
	float b = rand((ij+vec2(1.,0.)));
	float c = rand((ij+vec2(0.,1.)));
	float d = rand((ij+vec2(1.,1.)));
	float x1 = mix(a, b, xy.x);
	float x2 = mix(c, d, xy.x);
	return mix(x1, x2, xy.y);
}


	float pNoise(vec2 p, int res){
		// p+=u_noise_pan;
		float persistance = .5;
		float n = 0.;
		float normK = 0.;
		float f = 4.;
		float amp = 1.;
		int iCount = 0;
		//noprotect
		for (int i = 0; i<50; i++){
			n+=amp*noise(p, f);
			f*=2.;
			normK+=amp;
			amp*=persistance;
			if (iCount == res) break;
			iCount++;
		}
		float nf = n/normK;
		return nf*nf*nf*nf;
	}

	vec2 random2( vec2 p ) {
			return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
	}

`

// === Tab: frag ===
const frag = `
	precision highp float;

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;
	uniform vec3 u_lightDir;
	uniform vec3 u_col;
	uniform mat3 uNormalMatrix;
	uniform float u_pixelDensity;
	uniform sampler2D u_tex;

	//attributes, in
	varying vec4 var_centerGlPosition;
	varying vec3 var_vertNormal;
	varying vec2 var_vertTexCoord;

	${frag_functions_default}

	void main(){
		vec2 st = var_vertTexCoord.xy /u_resolution; 

    st.x += cnoise( vec3(st*5., 1.) )/5.0;  
   st.y -= cnoise( vec3(st*5., 1.) )/5.0;  
     // st.x += cnoise( vec3(st*1000., 1.) )/5.0; 

		 // st.x += pNoise( st, 500 );

		vec3 color = vec3(0.);
		vec4 texColor = texture2D(u_tex, st);



		gl_FragColor= vec4(color,1.0)+texColor;
	}
`





// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

